package co.com.ancas.images.adapter;

import co.com.ancas.models.model.ImageUpload;
import co.com.ancas.models.utils.TestMock;
import com.cloudinary.Cloudinary;
import com.cloudinary.Uploader;
import com.cloudinary.utils.ObjectUtils;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.ArgumentCaptor;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import java.io.IOException;
import java.util.HashMap;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.when;

@ExtendWith(MockitoExtension.class)
class CloudinaryAdapterTest {
    @Mock
    private Cloudinary cloudinary;
    @Mock
    private Uploader uploader;
    @InjectMocks
    private CloudinaryAdapter cloudinaryAdapter;
    private ImageUpload imageUpload;
    private ArgumentCaptor<String> stringArgumentCaptor;
    private ArgumentCaptor<Map> mapArgumentCaptor;

    @BeforeEach
    void setUp() {
        stringArgumentCaptor = ArgumentCaptor.forClass(String.class);
        mapArgumentCaptor = ArgumentCaptor.forClass(Map.class);
        imageUpload = TestMock.imageUpload();
        imageUpload.setBase64("");
    }

    @Test
    void deleteTest() throws IOException {
        //Arrange
        when(cloudinary.uploader()).thenReturn(uploader);
        when(uploader.destroy(stringArgumentCaptor.capture(),mapArgumentCaptor.capture())).thenReturn(ObjectUtils.emptyMap());
        //Act
        cloudinaryAdapter.delete("id");
        //Assert
        assertEquals("id",stringArgumentCaptor.getValue());
        assertTrue(mapArgumentCaptor.getValue().isEmpty());
    }

    @Test
    void uploadTest() throws IOException {
        //Arrange
        when(cloudinary.uploader()).thenReturn(uploader);
        when(uploader.upload(any(),any())).thenReturn(new HashMap<>());
        //Act
        Map response=cloudinaryAdapter.upload(imageUpload);
        //Assert
        assertNotNull(response);
        assertTrue(response.isEmpty());
    }

}